command:
// ==========================================
// LUNAS WIRKUNG: KÖDER (RONDRA)
//
// - fester Kompendium-Akteur „Rondras Köder“
// - nur Erwachte können die Gabe wirken
// - Dauer: QS Minuten
// - GM erzeugt den Köder automatisch
// - unverknüpfter Token neben dem Wirkenden
// - vorübergehende Besitzerrechte
// - Quelleffekt und Köder-Effekt über Block 6
// - gekoppelte Bereinigung über Sitzungs-ID
// - Tokenlöschung beendet die Wirkung
// - Wirkungsende entfernt den Köder
// - öffentliche Karte + roter GM-Button
// ==========================================


// +++ 0 - GLOBALE KÖDER-WÄCHTER +++++++++++++++++++++++++++++++

if (globalThis._dskKoederDeleteEffectHook) {
    Hooks.off("deleteActiveEffect", globalThis._dskKoederDeleteEffectHook);
}
if (globalThis._dskKoederDeleteTokenHook) {
    Hooks.off("deleteToken", globalThis._dskKoederDeleteTokenHook);
}

globalThis._dskKoederCleanupAktiv ||= new Set();

const _dskKoederAktiverGM = () => {
    const gms = game.users.filter(user => user.isGM && user.active)
        .sort((a, b) => String(a.id).localeCompare(String(b.id)));
    return gms[0] ? game.user.id === gms[0].id : game.user.isGM;
};

const _dskKoederLadeActor = async uuid => {
    if (!uuid) return null;
    try {
        const doc = await fromUuid(uuid);
        return doc?.documentName === "Token" ? doc.actor : doc || null;
    } catch {
        return null;
    }
};

const _dskKoederEntferneRechte = async ({ actor, sessionId }) => {
    if (!actor || !sessionId) return;

    const sitzungen = foundry.utils.deepClone(
        actor.getFlag("dsk", "koederSitzungen") || {}
    );
    const basis = actor.getFlag("dsk", "koederBasisRechte");

    delete sitzungen[sessionId];

    if (!Object.keys(sitzungen).length) {
        await actor.update({
            ownership: foundry.utils.deepClone(basis || actor.ownership || {})
        });

        if (actor.getFlag("dsk", "koederBasisRechte") !== undefined) {
            await actor.unsetFlag("dsk", "koederBasisRechte");
        }
        if (actor.getFlag("dsk", "koederSitzungen") !== undefined) {
            await actor.unsetFlag("dsk", "koederSitzungen");
        }
        return;
    }

    const ownership = foundry.utils.deepClone(basis || actor.ownership || {});

    for (const sitzung of Object.values(sitzungen)) {
        for (const userId of sitzung?.userIds || []) {
            if (game.users.get(userId)) {
                ownership[userId] = CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER;
            }
        }
    }

    await actor.update({
        ownership,
        "flags.dsk.koederSitzungen": sitzungen
    });
};

const _dskKoederBereinige = async effect => {
    if (!_dskKoederAktiverGM() ||
        effect?.getFlag("dsk", "isKoederQuelle") !== true) return false;

    const sessionId = effect.getFlag("dsk", "koederSessionId");
    if (!sessionId || globalThis._dskKoederCleanupAktiv.has(sessionId)) return false;

    globalThis._dskKoederCleanupAktiv.add(sessionId);

    try {
        const scene = game.scenes.get(effect.getFlag("dsk", "sceneId")) || canvas.scene;
        const tokenId = effect.getFlag("dsk", "koederTokenId");
        const koederActor = await _dskKoederLadeActor(
            effect.getFlag("dsk", "koederActorUuid")
        );

        if (scene?.tokens.get(tokenId)) {
            await scene.deleteEmbeddedDocuments(
                "Token",
                [tokenId],
                { dskKoederCleanup: true }
            );
        }

        if (koederActor) {
            await _dskKoederEntferneRechte({ actor: koederActor, sessionId });
        }

        return true;
    } finally {
        setTimeout(
            () => globalThis._dskKoederCleanupAktiv.delete(sessionId),
            500
        );
    }
};

globalThis._dskKoederDeleteEffectHook = Hooks.on(
    "deleteActiveEffect",
    async effect => {
        try {
            await _dskKoederBereinige(effect);
        } catch (error) {
            console.error("Köder: Bereinigung fehlgeschlagen.", error);
        }
    }
);

globalThis._dskKoederDeleteTokenHook = Hooks.on(
    "deleteToken",
    async (token, options) => {
        if (!_dskKoederAktiverGM() ||
            options?.dskKoederCleanup ||
            token.getFlag("dsk", "isRondrasKoeder") !== true) return;

        const casterActor = await _dskKoederLadeActor(
            token.getFlag("dsk", "spawnedByUuid")
        );
        const sessionId = token.getFlag("dsk", "koederSessionId");

        const quelleffekt = casterActor?.effects?.find(effect =>
            effect.getFlag("dsk", "isKoederQuelle") === true &&
            effect.getFlag("dsk", "koederSessionId") === sessionId
        );

        if (quelleffekt) await quelleffekt.delete();
    }
);


// +++ 1 - INIT-MODUS ++++++++++++++++++++++++++++++++++++++++++

if (typeof args !== "undefined" && args[0] === "WeckerAufruf") {
    globalThis._dskKoederInit = true;
    return;
}


// +++ 2 - NORMALE AUSFÜHRUNG ++++++++++++++++++++++++++++++++++

(async function () {
const macroUuid = this?.uuid || game.macros.getName("Köder")?.uuid || null;

// +++ 3 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt =
    !globalThis.DSK?.Effekt?.Anwenden ||
    !globalThis.DSK?.EffektEnde?.Register ||
    !globalThis.DSK?.QS?.Ermitteln ||
    !globalThis.DSK?.Token?.Finde ||
    !globalThis.DSK?.Wesen?.match ||
    !globalThis.DSK?.Empfaenger?.Besitzer ||
    !globalThis.DSK?.GMAnfrage?.Speichern ||
    !globalThis.DSK?.GMAnfrage?.Finden ||
    !globalThis.DSK?.GMAnfrage?.Lesen ||
    !globalThis.DSK?.GMAnfrage?.Loeschen ||
    !globalThis.DSK?.GabenUI?.GMMakroButton ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);
    if (!fwMacro?.execute) {
        return ui.notifications.error(
            "Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!"
        );
    }

    await fwMacro.execute();
    await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;

if (
    !DSK_FW?.Effekt?.Anwenden ||
    !DSK_FW?.EffektEnde?.Register ||
    !DSK_FW?.QS?.Ermitteln ||
    !DSK_FW?.Token?.Finde ||
    !DSK_FW?.Wesen?.match ||
    !DSK_FW?.Empfaenger?.Besitzer ||
    !DSK_FW?.GMAnfrage?.Speichern ||
    !DSK_FW?.GMAnfrage?.Finden ||
    !DSK_FW?.GMAnfrage?.Lesen ||
    !DSK_FW?.GMAnfrage?.Loeschen ||
    !DSK_FW?.GabenUI?.GMMakroButton ||
    !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
    !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
) {
    return ui.notifications.error(
        "Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!"
    );
}

// +++ 4 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++

const gabenName = "Köder", vollerName = "Köder (Rondra)", ahne = "Rondra";
const flagKey = "pendingKoederRondra", endeKey = "rondraKoeder";
const koederUuid = "Compendium.dsk-havena-und-umland.kreaturen-havena-und-umland.Actor.PKWJVMN4L8loXnSQ";
const koederName = "Rondras Köder";
const quellFlag = "koederQuelle";
const endeText = "Der Köder zerfällt wieder zu gewöhnlicher Erde.";

const basisBeschreibung =
    `Etwas aufgehobene Erde nimmt die Gestalt eines kleinen lebenden Tieres an.` +
    `<br><br>Der Köder bewegt sich mit <b>GS 3</b> vom Rondrakind weg und zieht Feinde auf sich.`;

DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

// +++ 5 - HELFER ++++++++++++++++++++++++++++++++++++++++++++++

const raeumeQSAuf = async actor => {
    if (actor?.getFlag("world", "letzteGabenQS") !== undefined) {
        await actor.unsetFlag("world", "letzteGabenQS");
    }
    if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) {
        await actor.unsetFlag("world", "letzteGabenMessageId");
    }
};

const findeQuelleffekt = actor => actor?.effects?.find(effect =>
    (effect.name || effect.label || "") === vollerName &&
    effect.getFlag("dsk", "isKoederQuelle") === true
) || null;

const findeImportiertenKoeder = () => game.actors.find(actor =>
    actor.getFlag("dsk", quellFlag) === koederUuid ||
    actor.getFlag("core", "sourceId") === koederUuid
) || null;

const ladeOderImportiereKoeder = async () => {
    let actor = findeImportiertenKoeder();
    if (actor) return actor;

    const quelle = await fromUuid(koederUuid).catch(() => null);
    if (!quelle) throw new Error("Der Akteur „Rondras Köder“ wurde nicht gefunden.");

    const data = quelle.toObject();
    delete data._id;
    delete data.folder;
    delete data.sort;

    foundry.utils.setProperty(data, `flags.dsk.${quellFlag}`, koederUuid);
    foundry.utils.setProperty(data, "flags.core.sourceId", koederUuid);

    actor = await Actor.create(data, { renderSheet: false });
    if (!actor) throw new Error("Rondras Köder konnte nicht importiert werden.");

    return actor;
};

const fuegeRechteHinzu = async ({ actor, sessionId, userIds }) => {
    const sitzungen = foundry.utils.deepClone(
        actor.getFlag("dsk", "koederSitzungen") || {}
    );

    let basis = actor.getFlag("dsk", "koederBasisRechte");
    if (!basis || !Object.keys(sitzungen).length) {
        basis = foundry.utils.deepClone(actor.ownership || {});
    }

    sitzungen[sessionId] = {
        userIds: [...new Set(userIds)],
        erstellt: Date.now()
    };

    const ownership = foundry.utils.deepClone(basis);

    for (const sitzung of Object.values(sitzungen)) {
        for (const userId of sitzung.userIds || []) {
            if (game.users.get(userId)) {
                ownership[userId] = CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER;
            }
        }
    }

    await actor.update({
        ownership,
        "flags.dsk.koederBasisRechte": basis,
        "flags.dsk.koederSitzungen": sitzungen
    });
};

const erzeugeKoederToken = async ({
    koederActor,
    casterActor,
    casterToken,
    sessionId
}) => {
    const x = casterToken.document.x + canvas.grid.size;
    const y = casterToken.document.y;

    const vorlage = await koederActor.getTokenDocument({
        x,
        y,
        elevation: casterToken.document.elevation || 0,
        hidden: false,
        actorLink: false
    });

    if (!vorlage) throw new Error("Die Tokenvorlage konnte nicht erzeugt werden.");

    const data = vorlage.toObject();
    delete data._id;

    Object.assign(data, {
        x,
        y,
        elevation: casterToken.document.elevation || 0,
        hidden: false,
        actorId: koederActor.id,
        actorLink: false,
        disposition: casterToken.document.disposition
    });

    data.texture = foundry.utils.deepClone(data.texture || {});

    if (!String(data.texture.src || "").trim()) {
        data.texture.src =
            koederActor.prototypeToken?.texture?.src ||
            koederActor.img ||
            DSK_FW.Symbol(ahne);
    }

    data.delta = foundry.utils.deepClone(data.delta || {});

    foundry.utils.setProperty(data, "flags.dsk.isRondrasKoeder", true);
    foundry.utils.setProperty(data, "flags.dsk.spawnedByUuid", casterActor.uuid);
    foundry.utils.setProperty(data, "flags.dsk.koederSessionId", sessionId);

    foundry.utils.setProperty(data, "delta.flags.dsk.isRondrasKoeder", true);
    foundry.utils.setProperty(data, "delta.flags.dsk.spawnedByUuid", casterActor.uuid);
    foundry.utils.setProperty(data, "delta.flags.dsk.koederSessionId", sessionId);

    const [token] = await canvas.scene.createEmbeddedDocuments("Token", [data]);

    if (!token?.actor) {
        if (token) {
            await canvas.scene.deleteEmbeddedDocuments("Token", [token.id])
                .catch(() => {});
        }

        throw new Error("Der unverknüpfte Köder-Token konnte nicht erzeugt werden.");
    }

    await token.actor.update({
        "flags.dsk.isRondrasKoeder": true,
        "flags.dsk.spawnedByUuid": casterActor.uuid,
        "flags.dsk.koederSessionId": sessionId
    }, {
        dskKoederSetup: true
    });

    return token;
};

// +++ 6 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++++++

const verarbeiteAnfrage = async (casterActor, daten) => {
    if (!casterActor || !daten || !_dskKoederAktiverGM()) return false;

    if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
        ui.notifications.warn(
            `Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`
        );
        return false;
    }

    const casterToken = DSK_FW.Token.Finde(
        casterActor,
        daten.casterTokenId,
        daten.casterTokenUuid
    );

    if (!casterToken) {
        ui.notifications.warn(
            `Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde nicht gefunden!`
        );
        return false;
    }

    if (findeQuelleffekt(casterActor)) {
        ui.notifications.warn(
            `Luna sagt 🌙: ${casterActor.name} besitzt bereits einen aktiven Köder!`
        );
        return false;
    }

    const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
    const dauerMinuten = qs;
    const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
    const sessionId = `koeder-${Date.now()}-${foundry.utils.randomID()}`;

    let koederActor = null;
    let koederToken = null;
    let quelleffekt = null;

    try {
        koederActor = await ladeOderImportiereKoeder();

        const userIds = new Set(
            DSK_FW.Empfaenger.Besitzer(casterActor)
        );

        if (daten.requestedByUserId && game.users.get(daten.requestedByUserId)) {
            userIds.add(daten.requestedByUserId);
        }

        await fuegeRechteHinzu({
            actor: koederActor,
            sessionId,
            userIds: [...userIds]
        });

        koederToken = await erzeugeKoederToken({
            koederActor,
            casterActor,
            casterToken,
            sessionId
        });

        quelleffekt = await DSK_FW.Effekt.Anwenden({
            name: vollerName,
            ahne,
            beschreibung:
                `${basisBeschreibung}` +
                `<br><br><b>Erschaffener Köder:</b> ${koederActor.name}`,
            gabeZiel: "",
            qs,
            ziel: casterActor,
            showIcon: 1,
            duration: {
                seconds: dauerMinuten * 60,
                startTime: game.time.worldTime
            },
            flags: {
                dsk: {
                    isKoederQuelle: true,
                    casterUuid: casterActor.uuid,
                    qs,
                    sceneId: canvas.scene.id,
                    koederActorUuid: koederActor.uuid,
                    koederTokenUuid: koederToken.uuid,
                    koederTokenId: koederToken.id,
                    koederSessionId: sessionId,
                    wirkungsende: {
                        sfName: endeKey,
                        basisEffektName: vollerName,
                        beschreibungFuerEnde: endeText
                    }
                }
            }
        });

        if (!quelleffekt) {
            throw new Error("Der Quelleffekt konnte nicht angelegt werden.");
        }

        const koederEffekt = await DSK_FW.Effekt.Anwenden({
            name: "Köder",
            ahne,
            beschreibung:
                `Dieses Wesen ist der von <b>${casterName}</b> erschaffene Köder und zieht Feinde auf sich.`,
            gabeZiel: "",
            qs,
            ziel: koederToken.actor,
            showIcon: 1,
            flags: {
                dsk: {
                    isKoederZiel: true,
                    casterUuid: casterActor.uuid,
                    sourceEffectUuid: quelleffekt.uuid,
                    koederSessionId: sessionId
                }
            }
        });

        if (!koederEffekt) {
            throw new Error("Der Effekt auf Rondras Köder konnte nicht angelegt werden.");
        }

        const quelleKorrekt =
            quelleffekt.getFlag("dsk", "isKoederQuelle") === true &&
            quelleffekt.getFlag("dsk", "koederSessionId") === sessionId &&
            quelleffekt.getFlag("dsk", "koederTokenId") === koederToken.id;

        const koederKorrekt =
            koederEffekt.getFlag("dsk", "isKoederZiel") === true &&
            koederEffekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
            koederEffekt.getFlag("dsk", "koederSessionId") === sessionId;

        if (!quelleKorrekt || !koederKorrekt) {
            throw new Error("Die Köder-Verknüpfung wurde nicht vollständig angelegt.");
        }

        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId: daten.messageId,
            gabenName: vollerName,
            ahne,
            beschreibung: basisBeschreibung,
            wirkender: casterName,
            ziele: [{
                name: koederActor.name,
                rolle: "Erschaffener Köder"
            }],
            misserfolge: [],
            dauerText: `${dauerMinuten} Minuten`,
            erfolgreich: true
        });

        ui.notifications.info(
            `Luna sagt 🌙: ${koederActor.name} wurde neben ${casterName} erschaffen.`
        );

        return true;

    } catch (error) {
        console.error("Köder: Erschaffung fehlgeschlagen.", error);

        if (quelleffekt) {
            await quelleffekt.delete().catch(() => {});
        }

        if (koederToken && canvas.scene.tokens.get(koederToken.id)) {
            await canvas.scene.deleteEmbeddedDocuments(
                "Token",
                [koederToken.id],
                { dskKoederCleanup: true }
            ).catch(() => {});
        }

        if (koederActor) {
            await _dskKoederEntferneRechte({
                actor: koederActor,
                sessionId
            }).catch(() => {});
        }

        await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
            messageId: daten.messageId,
            gabenName: vollerName,
            ahne,
            beschreibung: basisBeschreibung,
            wirkender: casterName,
            ziele: [],
            misserfolge: [{ name: koederName }],
            dauerText: `${dauerMinuten} Minuten`,
            erfolgreich: false
        }).catch(() => {});

        ui.notifications.error(
            `Luna sagt 🌙: Köder konnte nicht erschaffen werden: ${error?.message || error}`
        );

        return true;
    }
};

// +++ 7 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++++++

if (game.user.isGM) {
    const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

    if (anfragen.length) {
        for (const casterActor of anfragen) {
            const daten = DSK_FW.GMAnfrage.Lesen(casterActor, flagKey);

            if (daten && await verarbeiteAnfrage(casterActor, daten)) {
                await DSK_FW.GMAnfrage.Loeschen(casterActor, flagKey);
            }
        }

        return;
    }
}

// +++ 8 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++++++

let casterActor =
    canvas.tokens.controlled[0]?.actor ||
    game.user.character ||
    null;

if (!casterActor) {
    casterActor =
        canvas.tokens.placeables
            .map(token => token.actor)
            .find(actor =>
                actor?.getFlag("world", "letzteGabenQS") !== undefined
            ) ||
        game.actors.find(actor =>
            actor.getFlag("world", "letzteGabenQS") !== undefined
        ) ||
        null;
}

if (!casterActor) {
    return ui.notifications.warn(
        "Luna sagt 🌙: Kein Wirkender gefunden!"
    );
}

if (!game.user.isGM && !casterActor.isOwner) {
    return ui.notifications.warn(
        "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
    );
}

const casterToken = DSK_FW.Token.Finde(casterActor);

if (!casterToken) {
    return ui.notifications.warn(
        "Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!"
    );
}

const casterName = DSK_FW.ResolveTokenName(casterActor);

if (!DSK_FW.Wesen.match(
    casterActor,
    ["erwacht", "erwachter", "erwachte"]
)) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName,
        ahne,
        beschreibung:
            "Diese Gabe kann nur von einem Erwachten gewirkt werden.",
        wirkender: casterName,
        ziele: [],
        misserfolge: [{ name: casterName }],
        dauerText: "0 Minuten",
        gmBereich: false,
        angewendet: true,
        erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    return;
}

if (findeQuelleffekt(casterActor)) {
    return ui.notifications.warn(
        `Luna sagt 🌙: ${casterName} besitzt bereits einen aktiven Köder!`
    );
}

const qs = DSK_FW.QS.Ermitteln({
    actor: casterActor,
    gabenName,
    suchbegriffe: ["Köder Probe", "Köder"],
    testDataObj:
        typeof testData !== "undefined"
            ? testData
            : null,
    fallback: 0,
    protokollieren: true
});

if (qs <= 0) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName,
        ahne,
        beschreibung:
            "Die Erde nimmt keine lebendige Gestalt an.",
        wirkender: casterName,
        ziele: [],
        misserfolge: [{ name: casterName }],
        dauerText: "0 Minuten",
        gmBereich: false,
        angewendet: true,
        erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    await raeumeQSAuf(casterActor);
    return;
}

// +++ 9 - GEMEINSAME KARTE + GM-ANFRAGE +++++++++++++++++++++++

const dauerMinuten = qs;
const gmLink = DSK_FW.GabenUI.GMMakroButton(
    macroUuid,
    "Effekt anwenden",
    "Das Makro muss durch die Spielleitung ausgeführt werden."
);

const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
    gabenName: vollerName,
    ahne,
    beschreibung: basisBeschreibung,
    wirkender: casterName,
    ziele: [{
        name: koederName,
        rolle: "Zu erschaffender Köder"
    }],
    misserfolge: [],
    dauerText: `${dauerMinuten} Minuten`,
    gmLink,
    gmBereich: !game.user.isGM,
    anfragenderUserId: game.user.id
});

if (!nachricht) {
    await raeumeQSAuf(casterActor);

    return ui.notifications.error(
        "Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!"
    );
}

const daten = {
    casterUuid: casterActor.uuid,
    casterName,
    casterTokenId: casterToken.id,
    casterTokenUuid:
        casterToken.document?.uuid ||
        casterToken.uuid ||
        null,
    qs,
    sceneId: canvas.scene?.id || null,
    requestedByUserId: game.user.id,
    messageId: nachricht.id,
    macroUuid,
    erstellt: Date.now()
};

// +++ 10 - DIREKT ODER GM-ANFRAGE +++++++++++++++++++++++++++++

if (game.user.isGM) {
    await verarbeiteAnfrage(casterActor, daten);
    await raeumeQSAuf(casterActor);
    return;
}

